using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1: EF Core 9 renamed discriminator from "Discriminator" to "$type".
            // Preserve "Discriminator" so existing 500K documents and raw SQL queries keep working.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2: EF Core 9 changed id from "Product|<key>" to just "<key>".
            // Preserve the EF Core 8 composite format with an explicit shadow property.
            entity.Property<string>("__id")
                .ToJsonProperty("id")
                .HasValueGeneratorFactory<CompositeIdValueGeneratorFactory>();

            entity.HasKey("__id");
        });

        // BREAKING CHANGE 3: HasIndex is not supported by the Cosmos provider.
        // It was silently ignored in EF 8 but may throw in EF 9. Removed.
    }
}

/// <summary>
/// Generates id values in the EF Core 8 format: "Product|{key}"
/// </summary>
class CompositeIdValueGeneratorFactory : ValueGeneratorFactory
{
    public override ValueGenerator Create(
        Microsoft.EntityFrameworkCore.Metadata.IProperty property,
        Microsoft.EntityFrameworkCore.Metadata.ITypeBase typeBase)
        => new CompositeIdValueGenerator();
}

class CompositeIdValueGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(Microsoft.EntityFrameworkCore.ChangeTracking.EntityEntry entry)
        => $"Product|{entry.Property("Id").CurrentValue}";
}

